import pandas as pd, json, glob, sqlite3

sample_req = pd.read_csv('dataset/sample_deletion_requests.csv')
sample_out = pd.read_csv('dataset/sample_output.csv')
users = pd.read_csv('dataset/user_identities.csv')
audit = pd.read_csv('dataset/user_audit_log.csv')
manifest = pd.read_csv('dataset/evidence_files.csv')

# Build identity graph for each user
user_graphs = {}
for _, u in users.iterrows():
    uid = u['user_id']
    user_graphs[uid] = {
        'user_id': uid,
        'emails': {str(u['email']).strip().lower()} if pd.notna(u['email']) else set(),
        'phones': {str(u['phone']).strip()} if pd.notna(u['phone']) else set(),
        'hashes': {str(u['email_hash']).strip().lower()} if pd.notna(u['email_hash']) else set(),
        'names': {str(u['name']).strip().lower()} if pd.notna(u['name']) else set(),
    }

email_to_uid = {}
for uid, g in user_graphs.items():
    for em in g['emails']:
        email_to_uid[em] = uid

for _, a in audit.iterrows():
    uid = a['user_id']
    if uid not in user_graphs:
        user_graphs[uid] = {'user_id': uid, 'emails': set(), 'phones': set(), 'hashes': set(), 'names': set()}
    fn = a['field_name']
    for val in [a['old_value'], a['new_value']]:
        if pd.notna(val):
            val_s = str(val).strip()
            if fn == 'email':
                user_graphs[uid]['emails'].add(val_s.lower())
                email_to_uid[val_s.lower()] = uid
            elif fn == 'phone':
                user_graphs[uid]['phones'].add(val_s)
            elif fn == 'name':
                user_graphs[uid]['names'].add(val_s.lower())

print(f'Indexed {len(user_graphs)} users and {len(email_to_uid)} emails.')

# Test on case_01 to case_05
for idx, r in sample_req.merge(sample_out, on='case_id').head(5).iterrows():
    cid = r['case_id']
    req_email = str(r['email']).strip().lower()
    uid = email_to_uid.get(req_email)
    g = user_graphs.get(uid)
    steps = json.loads(r['steps_json'])
    expected_res = [s['resource_id'] for s in steps]
    print(f'{cid} ({uid}): Expected resources: {expected_res}, User emails: {g[\"emails\"]}')
"

