import pandas as pd, json, sqlite3

sample_req = pd.read_csv('dataset/sample_deletion_requests.csv')
sample_out = pd.read_csv('dataset/sample_output.csv')
users = pd.read_csv('dataset/user_identities.csv')
audit = pd.read_csv('dataset/user_audit_log.csv')
activity = pd.read_csv('dataset/system_activity.csv')
manifest = pd.read_csv('dataset/evidence_files.csv').set_index('file_id')

email_to_uid = {}
for _, u in users.iterrows():
    email_to_uid[str(u['email']).strip().lower()] = u['user_id']
for _, a in audit.iterrows():
    if a['field_name'] == 'email':
        if pd.notna(a['old_value']):
            email_to_uid[str(a['old_value']).strip().lower()] = a['user_id']
        if pd.notna(a['new_value']):
            email_to_uid[str(a['new_value']).strip().lower()] = a['user_id']

# Group cases by the cited evidence file
ev_groups = {}
for idx, r in sample_req.merge(sample_out, on='case_id').iterrows():
    cid = r['case_id']
    steps = json.loads(r['steps_json'])
    eids = tuple(sorted(list({s['evidence_id'] for s in steps if s.get('evidence_id')})))
    ev_groups.setdefault(eids, []).append((cid, r['email'], r['deletion_status']))

for eids, cases in sorted(ev_groups.items(), key=lambda x: str(x[0])):
    print(f'Evidence: {eids}')
    for cid, em, st in cases:
        uid = email_to_uid.get(em)
        print(f'   {cid} ({uid}, {em}): {st}')
"

