import os, glob, json, sqlite3, time, re
import pandas as pd

t0 = time.time()
manifest = pd.read_csv('dataset/evidence_files.csv')

# Let's count parsed records
total_records = 0
for idx, row in manifest.iterrows():
    fpath = os.path.join('dataset', row['file_path'])
    if not os.path.exists(fpath):
        continue
    if fpath.endswith('.sql'):
        conn = sqlite3.connect(':memory:')
        with open(fpath) as fp:
            conn.executescript(fp.read())
        cursor = conn.cursor()
        cursor.execute(\"SELECT name FROM sqlite_master WHERE type='table'\")
        tables = [r[0] for r in cursor.fetchall() if r[0] != 'snapshot_scope']
        for tbl in tables:
            cursor.execute(f'SELECT COUNT(*) FROM \"{tbl}\"')
            total_records += cursor.fetchone()[0]
    elif fpath.endswith('.json'):
        with open(fpath) as fp:
            d = json.load(fp)
            if 'records' in d:
                total_records += len(d['records'])
            elif 'snapshots' in d:
                for s in d['snapshots']:
                    total_records += len(s.get('records', []))
            elif 'service_exports' in d:
                for s, exports in d['service_exports'].items():
                    for k, v in exports.items():
                        if isinstance(v, list):
                            total_records += len(v)
    elif fpath.endswith('.txt'):
        with open(fpath) as fp:
            total_records += len([l for l in fp if l.strip().startswith('-')])

print(f'Parsed {total_records} records across structured evidence files in {(time.time()-t0):.2f}s')
"

