manifest = pd.read_csv('dataset/evidence_files.csv').set_index('file_id')
manifest['cap_dt'] = pd.to_datetime(manifest['captured_at'])

# Load users and audit log
users_df = pd.read_csv('dataset/user_identities.csv')
audit_df = pd.read_csv('dataset/user_audit_log.csv')

user_graph = {}
email_to_uid = {}
for _, u in users_df.iterrows():
    uid = u['user_id']
    user_graph[uid] = {
        'user_id': uid,
        'emails': {str(u['email']).strip().lower()} if pd.notna(u['email']) else set(),
        'phones': {str(u['phone']).strip()} if pd.notna(u['phone']) else set(),
        'hashes': {str(u['email_hash']).strip().lower()} if pd.notna(u['email_hash']) else set(),
        'names': {str(u['name']).strip().lower()} if pd.notna(u['name']) else set(),
    }
    if pd.notna(u['email']):
        email_to_uid[str(u['email']).strip().lower()] = uid

for _, a in audit_df.iterrows():
    uid = a['user_id']
    if uid not in user_graph:
        user_graph[uid] = {'user_id': uid, 'emails': set(), 'phones': set(), 'hashes': set(), 'names': set()}
    fn = a['field_name']
    for v in [a['old_value'], a['new_value']]:
        if pd.notna(v):
            vs = str(v).strip()
            if fn == 'email':
                user_graph[uid]['emails'].add(vs.lower())
                email_to_uid[vs.lower()] = uid
            elif fn == 'phone':
                user_graph[uid]['phones'].add(vs)
            elif fn == 'name':
                user_graph[uid]['names'].add(vs.lower())

print(f'User graph built for {len(user_graph)} users.')
"

